195: #define I2S_OPT_FRAME_CLK_MASTER            I2S_OPT_FRAME_CLK_CONTROLLER __DEPRECATED_MACRO
196: /** @deprecated @see I2S_OPT_FRAME_CLK_TARGET */
197: #define I2S_OPT_FRAME_CLK_SLAVE             I2S_OPT_FRAME_CLK_TARGET __DEPRECATED_MACRO
198: 
199: /** @brief Loop back mode.
200:  *
201:  * In loop back mode RX input will be connected internally to TX output.
202:  * This is used primarily for testing.
203:  */
204: #define I2S_OPT_LOOPBACK                    BIT(7)
205: 
206: /** @brief Ping pong mode
