763: static int audio_allocbuffer(FAR struct audio_upperhalf_s *upper,
764:                              FAR struct audio_buf_desc_s *bufdesc)
765: {
766:   FAR struct audio_lowerhalf_s *lower = upper->dev;
767:   FAR struct ap_buffer_s *apb;
768:   bool share = false;
769:   FAR void *newaddr;
770:   int ret;
771: 
772:   if (bufdesc->u.pbuffer == NULL)
773:     {
774:       if (upper->periods >= upper->nbuffers)
775:         {
776:           return 0;
777:         }
778: 
779:       bufdesc->u.pbuffer = &apb;
780:       share = true;
781:     }
782: 
783:   if (lower->ops->allocbuffer != NULL)
784:     {
785:       ret = lower->ops->allocbuffer(lower, bufdesc);
786:     }
787:   else
788:     {
789:       /* Perform a simple kumm_malloc operation assuming 1 session */
790: 
791:       ret = apb_alloc(bufdesc);
792:     }
793: 
794:   if (ret > 0 && share)
795:     {
796:       newaddr = kmm_realloc(upper->apbs,
797:                             (upper->periods + 1) * sizeof(*upper->apbs));
798:       if (newaddr == NULL)
799:         {
800:           audio_freebuffer(upper, bufdesc);
801:           return -ENOMEM;
802:         }
803: 
804:       upper->apbs = (FAR struct ap_buffer_s **)newaddr;
805:       upper->apbs[upper->periods] = apb;
806:       upper->periods++;
807:       bufdesc->u.pbuffer = NULL;
808:     }
809: 
810:   return ret;
811: }
