823: {
824:   FAR struct inode *inode = filep->f_inode;
825:   FAR struct audio_upperhalf_s *upper = inode->i_private;
826:   FAR struct audio_lowerhalf_s *lower = upper->dev;
827:   FAR struct audio_openpriv_s *priv = filep->f_priv;
828:   irqstate_t flags;
829:   int ret = OK;
830: 
831:   DEBUGASSERT(lower->ops->enqueuebuffer != NULL);
832: 
833:   if (bufdesc->u.buffer)
834:     {
835:       ret = lower->ops->enqueuebuffer(lower, bufdesc->u.buffer);
836:       if (ret != OK)
837:         {
838:           return ret;
839:         }
840: 
841:       flags = spin_lock_irqsave(&upper->spinlock);
842:       upper->status->head++;
843:       spin_unlock_irqrestore(&upper->spinlock, flags);
844:     }
845:   else
