656: /****************************************************************************
657:  * Name: nxplayer_filltone
658:  *
659:  *  Fill the generated tone data into the specified
660:  *  buffer.
661:  *
662:  ****************************************************************************/
663: 
664: static int nxplayer_filltone(FAR struct nxplayer_tone_s *tone,
665:                              FAR struct ap_buffer_s *apb)
666: {
667:   FAR uint16_t *samples;
668:   float value;
669:   size_t i;
670: 
671:   apb->nbytes = 0;
672:   apb->curbyte = 0;
673:   samples = (FAR uint16_t *)apb->samp;
674: 
675:   if (tone->cur_samps >= tone->total_samps)
676:     {
677:       return -ENODATA;
678:     }
679: 
680:   for (i = 0; i < apb->nmaxbytes / 4; i++)
681:     {
682:       value = sinf(2 * M_PI * tone->pitch_freq *
683:                    tone->cur_samps / tone->sample_rate);
684:       samples[i * 2 + 1] = samples[i * 2] = (uint16_t)(value * 10000);
685: 
686:       tone->cur_samps++;
687:       apb->nbytes += 4;
688: 
689:       if (tone->cur_samps >= tone->total_samps)
690:         {
691:           apb->flags |= AUDIO_APB_FINAL;
692:           break;
693:         }
694:     }
695: 
696:   return 0;
697: }
