699: /****************************************************************************
700:  * Name: nxplayer_readbuffer
701:  *
702:  *  Read the next block of data from the media file into the specified
703:  *  buffer.
704:  *
705:  ****************************************************************************/
706: 
707: static int nxplayer_readbuffer(FAR struct nxplayer_s *pplayer,
708:                                FAR struct ap_buffer_s *apb)
709: {
710:   int ret;
711: 
712:   /* Validate the file is still open.  It will be closed automatically when
713:    * we encounter the end of file (or, perhaps, a read error that we cannot
714:    * handle.
715:    */
716: 
717:   if (pplayer->fd == -1)
718:     {
719:       /* Return -ENODATA to indicate that there is nothing more to read from
720:        * the file.
721:        */
722: 
723:       return -ENODATA;
724:     }
725: 
726:   ret = pplayer->ops->fill_data(pplayer->fd, apb);
727:   if (ret < 0)
728:     {
729:       /* End of file or read error.. We are finished with this file in any
730:        * event.
731:        */
732: 
733:       close(pplayer->fd);
734:       pplayer->fd = -1;
735:     }
736: 
737:   return OK;
738: }
