740: /****************************************************************************
741:  * Name: nxplayer_enqueuebuffer
742:  *
743:  * Description:
744:  *   Enqueue the audio buffer in the downstream device.  Normally we are
745:  *   called with a buffer of data to be enqueued in the audio stream.
746:  *
747:  *   Be we may also receive an empty length buffer (with only the
748:  *   AUDIO_APB_FINAL set) in the event of certain read error occurs or in the
749:  *   event that the file was an exact multiple of the nmaxbytes size of the
750:  *   audio buffer.  In that latter case, we have an end of file with no bytes
751:  *   read.
752:  *
753:  *   These infrequent zero length buffers have to be passed through because
754:  *   the include the AUDIO_APB_FINAL flag that is needed to terminate the
755:  *   audio stream.
756:  *
757:  ****************************************************************************/
758: 
759: static int nxplayer_enqueuebuffer(FAR struct nxplayer_s *pplayer,
760:                                   FAR struct ap_buffer_s *apb)
761: {
762:   struct audio_buf_desc_s bufdesc;
763:   int ret;
764: 
765:   /* Now enqueue the buffer with the audio device.  If the number of
766:    * bytes in the file happens to be an exact multiple of the audio
767:    * buffer size, then we will receive the last buffer size = 0.  We
768:    * encode this buffer also so the audio system knows its the end of
769:    * the file and can do proper clean-up.
770:    */
771: 
772: #ifdef CONFIG_AUDIO_MULTI_SESSION
773:   bufdesc.session   = pplayer->session;
774: #endif
775:   bufdesc.numbytes  = apb->nbytes;
776:   bufdesc.u.buffer = apb;
777: 
778:   ret = ioctl(pplayer->dev_fd, AUDIOIOC_ENQUEUEBUFFER,
779:               (unsigned long)&bufdesc);
780:   if (ret < 0)
781:     {
782:       int errcode = errno;
783:       DEBUGASSERT(errcode > 0);
784: 
785:       auderr("ERROR: AUDIOIOC_ENQUEUEBUFFER ioctl failed: %d\n", errcode);
786:       return -errcode;
787:     }
788: 
789:   /* Return OK to indicate that we successfully read data from the file
790:    * (and we are not yet at the end of file)
791:    */
792: 
793:   return OK;
794: }
