796: /****************************************************************************
797:  * Name: nxplayer_jointhread
798:  ****************************************************************************/
799: 
800: static void nxplayer_jointhread(FAR struct nxplayer_s *pplayer)
801: {
802:   FAR void *value;
803:   int id = 0;
804: 
805:   if (gettid() == pplayer->play_id)
806:     {
807:       return;
808:     }
809: 
810:   pthread_mutex_lock(&pplayer->mutex);
811: 
812:   if (pplayer->play_id > 0)
813:     {
814:       id = pplayer->play_id;
815:       pplayer->play_id = 0;
816:     }
817: 
818:   pthread_mutex_unlock(&pplayer->mutex);
819: 
820:   if (id > 0)
821:     {
822:       pthread_join(id, &value);
823:     }
824: }
