834: static FAR void *nxplayer_playthread(pthread_addr_t pvarg)
835: {
836:   FAR struct nxplayer_s   *pplayer = (FAR struct nxplayer_s *)pvarg;
837:   struct audio_msg_s      msg;
838:   struct audio_buf_desc_s buf_desc;
839:   ssize_t                 size;
840:   bool                    running = true;
841:   bool                    streaming = true;
842:   bool                    failed = false;
843:   struct ap_buffer_info_s buf_info;
