853:   /* Query the audio device for its preferred buffer size / qty */
854: 
855:   if ((ret = ioctl(pplayer->dev_fd, AUDIOIOC_GETBUFFERINFO,
856:                   (unsigned long)&buf_info)) != OK)
857:     {
858:       /* Driver doesn't report its buffer size.  Use our default. */
859: 
860:       buf_info.buffer_size = CONFIG_AUDIO_BUFFER_NUMBYTES;
861:       buf_info.nbuffers = CONFIG_AUDIO_NUM_BUFFERS;
