864:   /* Create array of pointers to buffers */
865: 
866:   FAR struct ap_buffer_s *buffers[buf_info.nbuffers];
867: 
868:   /* Create our audio pipeline buffers to use for queueing up data */
869: 
870:   memset(buffers, 0, sizeof(buffers));
871: 
872:   for (x = 0; x < buf_info.nbuffers; x++)
873:     {
874:       /* Fill in the buffer descriptor struct to issue an alloc request */
875: 
876: #ifdef CONFIG_AUDIO_MULTI_SESSION
877:       buf_desc.session = pplayer->session;
878: #endif
879: 
880:       buf_desc.numbytes = buf_info.buffer_size;
881:       buf_desc.u.pbuffer = &buffers[x];
882: 
883:       ret = ioctl(pplayer->dev_fd, AUDIOIOC_ALLOCBUFFER,
884:                  (unsigned long)&buf_desc);
885:       if (ret != sizeof(buf_desc))
886:         {
887:           /* Buffer alloc Operation not supported or error allocating! */
888: 
889:           auderr("ERROR: Could not allocate buffer %d\n", x);
890:           running = false;
891:           goto err_out;
892:         }
893:     }
894: 
895:   /* Fill up the pipeline with enqueued buffers */
896: 
897:   for (x = 0; x < buf_info.nbuffers; x++)
898:     {
899:       /* Read the next buffer of data */
900: 
901:       if (pplayer->tone.sample_rate)
902:         {
903:           /* Fill the generated tone data into apb  */
904: 
905:           ret = nxplayer_filltone(&pplayer->tone, buffers[x]);
906:         }
907:       else
908:         {
909:           /* Fill the audio data of the file into apb */
910: 
911:           ret = nxplayer_readbuffer(pplayer, buffers[x]);
912:         }
913: 
914:       if (ret != OK)
915:         {
916:           /* nxplayer_readbuffer will return an error if there is no further
917:            * data to be read from the file.  This can happen normally if the
918:            * file is very small (less than will fit in
919:            * CONFIG_AUDIO_NUM_BUFFERS) or if an error occurs trying to read
920:            * from the file.
921:            */
922: 
923:           /* We are no longer streaming data from the file */
924: 
925:           streaming = false;
926: 
927:           if (x == 0)
928:             {
929:               /* No buffers read?  Should never really happen.  Even in the
930:                * case of a read failure, one empty buffer containing the
931:                * AUDIO_APB_FINAL indication will be returned.
932:                */
933: 
934:               running = false;
935:             }
936:         }
937: 
938:       /* Enqueue buffer by sending it to the audio driver */
939: 
940:       else
